input.old_string:
.media img {
  width: 100%;
  height: auto;
  max-height: 420px;
  object-fit: cover;
  display: block;
}

input.new_string:
.media img {
  width: 100%;
  height: auto;
  max-height: 420px;
  object-fit: cover;
  display: block;
  transition: transform 0.6s ease;
}

section.visible .media img {
  transform: scale(1.02);
}
